export function getStatsByCategory(category: CategorySlug): Stat[] {
  if (category === "all") return STATS;
  return STATS.filter((s) => s.category === category);
}

export function getRandomStat(excludeId?: number): Stat {
  const seenIds = new Set(getCleanSeenQuestionIds());
  let available = STATS.filter((s) => !seenIds.has(s.id));
  console.log("Questions vues actives :", seenIds.size, "Disponibles restantes :", available.length);
  if (available.length === 0) {
    available = excludeId ? STATS.filter((s) => s.id !== excludeId) : STATS;
  }
  if (excludeId) {
    const filtered = available.filter((s) => s.id !== excludeId);
    if (filtered.length > 0) available = filtered;
  }
  return available[Math.floor(Math.random() * available.length)];
}

export function getRandomStatByCategory(category: CategorySlug, excludeId?: number): Stat | null {
  const seenIds = new Set(getCleanSeenQuestionIds());
  const pool = getStatsByCategory(category);
  let available = pool.filter((s) => !seenIds.has(s.id));
  console.log("Questions vues actives :", seenIds.size, "Disponibles restantes :", available.length);
  if (available.length === 0) {
    available = excludeId ? pool.filter((s) => s.id !== excludeId) : pool;
  }
  if (excludeId) {
    const filtered = available.filter((s) => s.id !== excludeId);
    if (filtered.length > 0) available = filtered;
  }
  if (available.length === 0) return null;
  return available[Math.floor(Math.random() * available.length)];
}
